import re


class Kontakt:
    """En enkel klass som representerar en kontaktperson."""

    def __init__(self, namn, telefonnummer, epost):
        self.namn = namn
        self.telefonnummer = telefonnummer
        self.epost = epost

    def har_svenskt_telefonnummer(self):
        """Svenskt nationellt format, t.ex. 070-1234567 eller 0701234567."""
        return bool(re.fullmatch(r"0\d{1,3}-?\d{5,8}", self.telefonnummer))

    def har_internationellt_nummer(self):
        """Internationellt format, t.ex. +46701234567 eller +46 701234567."""
        return bool(re.fullmatch(r"\+\d{1,3}\s?\d{6,12}", self.telefonnummer))

    def har_korrekt_epost(self):
        """Enkel kontroll av att e-postadressen ser rimlig ut."""
        return bool(re.fullmatch(r"[^@\s]+@[^@\s]+\.[a-zA-Z]{2,}", self.epost))
